# Reel scripts for "Name, Place, Time": a recounting of the season-by-season close-read of
# *Something Was Wrong* (coercive-harm-framework, branch ccr-93dfe246-4ja9f0, commit 729dd3e,
# research/sww-corpus/). Every factual line is drawn from the close-read files; survivors keep
# the pseudonyms the show used. Testimony as broadcast (P2): allegations, not verdicts.
#
# Scene = one narration unit ("say") plus one on-screen card. Card kinds:
#   title  {big, small}             kinetic title
#   head   {head, body}             headline + body
#   quote  {q, by}                  pull quote
#   stat   {num, label}             big number
#   list   {head, items}            items reveal across the scene
#   cycle  {label, marks}           the six-stage ring; marks: y / p / n / o / d (present, partial, absent, not observable, not described)
#   bars   {head, rows:[(label, value, fmt)], ref}   horizontal bars

SERIES = "NAME · PLACE · TIME"
SUB = "A close-read of Something Was Wrong, S1–S10"

STAGES = ["LOVE\nBOMBING", "DEVALUE", "ISOLATE", "POISON\nTHE WELL", "DISCARD", "RETURN"]

REELS = [
  {"id": "01", "kicker": "INTRO", "accent": "#ff4d5e", "scenes": [
    {"say": "I read the first ten seasons of the podcast Something Was Wrong, in order. Every episode with a story in it. About seven hundred thousand words.",
     "card": {"t": "title", "big": "10 seasons.\nIn order.", "small": "≈ 710,000 words of survivor testimony"}},
    {"say": "The claim I was testing came to me primed. That across separate people, with separate lives, the harmful behaviours overlap so much that the only details that change are name, place and time.",
     "card": {"t": "title", "big": "Only the name,\nplace and time\nchange.", "small": "the claim, as put to me"}},
    {"say": "The cycle, as it was described to me. Love bombing. Devaluation. Isolation. Poisoning the well with the people in your care system. Discard. And then, often, a return.",
     "card": {"t": "cycle", "label": "the cycle, as stated", "marks": "yyyyyy"}},
    {"say": "Before I read a single episode, I wrote down what would refute it. A stage clearly absent while the perpetrator had every chance to perform it. Or behaviour that differs in kind, not just in name, place and time.",
     "card": {"t": "list", "head": "What would refute it", "items": ["A stage absent while the perpetrator had the chance", "Behaviour that differs in kind, not just in detail"]}},
    {"say": "Every case that broke the pattern got recorded as a divergence. Never smoothed over. And some cases did break it.",
     "card": {"t": "head", "head": "Divergences get recorded.\nNot smoothed.", "body": "Some cases did break the pattern."}},
    {"say": "This series is what I found, season by season. Everything in it is survivors' testimony as broadcast. Allegations, not verdicts.",
     "card": {"t": "title", "big": "Season\nby season.", "small": "testimony as broadcast · allegations, not verdicts"}},
  ]},

  {"id": "02", "kicker": "SEASON 1 · 2019", "accent": "#ff4d5e", "scenes": [
    {"say": "Season one. Sarah, thirty, a chiropractic assistant in Sacramento. The show calls her fiancé Dick.",
     "card": {"t": "title", "big": "Sarah\n& “Dick”", "small": "Sacramento · 2017–2018"}},
    {"say": "Nominally it's one story. In fact it holds at least six women who lived separate lives and never knew each other.",
     "card": {"t": "stat", "num": "6+", "label": "women who never knew each other"}},
    {"say": "More than one of them got the same flattering opening text. Word for word.",
     "card": {"t": "head", "head": "The same opening text.\nWord for word.", "body": "Sent to more than one woman."}},
    {"say": "He told more than one woman he had cancer. He attacked their church or their pastor early. He replaced their books.",
     "card": {"t": "list", "head": "Repeated across women", "items": ["A cancer story", "Early attacks on her church or pastor", "Her books and pastors replaced"]}},
    {"say": "He also invented people. Sockpuppet accounts called Kimmy and Brian coached Sarah, set her rules, and called her family codependent. He ordered a gift from Kimmy eighteen days after meeting her.",
     "card": {"t": "stat", "num": "18 days", "label": "after meeting her, he ordered a “gift from Kimmy”"}},
    {"say": "Sarah left. He called it a huge mistake, held a stalled refund over her like a lifeline, and logged into her accounts.",
     "card": {"t": "cycle", "label": "Sarah", "marks": "yyyyoy"}},
    {"say": "What it established: within one perpetrator, strong. Six women, one script. Across different perpetrators, only suggestive. That's what the next nine seasons were for.",
     "card": {"t": "head", "head": "One perpetrator: strong.\nAcross perpetrators: open.", "body": "The next nine seasons were the test."}},
  ]},

  {"id": "03", "kicker": "SEASON 2 · 2019", "accent": "#ffb547", "scenes": [
    {"say": "Season two has no romance at all. A small veterinary hospital. T, who rose to HR director. And Sylvia, a younger coworker, lower in the hierarchy.",
     "card": {"t": "title", "big": "T\n& “Sylvia”", "small": "a veterinary hospital · c. 2002–2006"}},
    {"say": "For about four years, Sylvia had cancer. Then it spread to the brain. There were self-inflicted incisions, saline injections, and a staged overdose, with T's own gifts and notes laid out on the bed.",
     "card": {"t": "stat", "num": "4 years", "label": "of fabricated, then self-induced, illness"}},
    {"say": "This is where love bombing changed shape. Not flattery. Need. A dying friend pulls you into an exam room, and you pour in. Meal trains. Rides to chemo. Five house moves.",
     "card": {"t": "head", "head": "Not flattery.\nNeed.", "body": "Love bombing coded by function, not form."}},
    {"say": "T, on how the lies were kept apart:",
     "card": {"t": "quote", "q": "A whole separate set of lies for each… none of us intersected.", "by": "T, season 2"}},
    {"say": "The one doubter, the boy's father, asked why his son was on seizure medication when nobody had ever seen a seizure. He was shouted down.",
     "card": {"t": "head", "head": "The doubter was\nshouted down.", "body": "A pattern that recurs in later seasons."}},
    {"say": "The big divergence: the power ran upward. A subordinate over a senior, running on obligation, not authority.",
     "card": {"t": "head", "head": "Power ran upward.", "body": "A subordinate over a senior, on obligation."}},
    {"say": "And the institutions. Child protective services, in T's words, didn't even investigate. T kept the syringes, filed the report, and was never told the outcome.",
     "card": {"t": "list", "head": "The record fell on the target", "items": ["CPS: “didn't even investigate”", "T kept the syringes and reported", "Never told the outcome"]}},
  ]},

  {"id": "04", "kicker": "SEASON 3 · 2019–20", "accent": "#a78bfa", "scenes": [
    {"say": "Season three. Central Pennsylvania. Three firefighter families. Victoria, her husband Ted, and their closest friend, Patty.",
     "card": {"t": "title", "big": "Victoria,\nTed & “Patty”", "small": "Central Pennsylvania · 2006–2018"}},
    {"say": "Patty and Ted were in a twelve-year affair. And for more than a decade, Patty was Victoria's care system, and poisoned every other part of it.",
     "card": {"t": "head", "head": "She was the care system.", "body": "And she poisoned every other part of it."}},
    {"say": "To the daughter-in-law, daily, for ten years: Victoria lies. To Ted: the daughter-in-law hates us. Ted told Victoria's own brother she was crazy.",
     "card": {"t": "list", "head": "A different story for each listener", "items": ["To the daughter-in-law: “Victoria lies”", "To Ted: “she hates us”", "To her brother: “she's crazy”"]}},
    {"say": "Victoria was called a liar for buying eggs instead of milk. Told she was cracking up. She went to counselling for years, and had a scan for suspected dementia, because Patty kept telling her she misremembered.",
     "card": {"t": "head", "head": "A dementia scan.", "body": "Because she was told she misremembered."}},
    {"say": "The purest instance of poisoning the well in the whole corpus.",
     "card": {"t": "cycle", "label": "Victoria", "marks": "yyyyoo"}},
    {"say": "New here: the husband was recruited. He adopted her habits. His family grieves him as both perpetrator and casualty.",
     "card": {"t": "head", "head": "A co-perpetrator,\nrecruited from inside.", "body": "He “adopted her habits.”"}},
    {"say": "Police did act, and produced a record. The only remedy they could offer was a no-contact letter.",
     "card": {"t": "head", "head": "Police acted.", "body": "The only remedy: a no-contact letter."}},
  ]},

  {"id": "05", "kicker": "SEASON 4 · 2020", "accent": "#ff4d5e", "scenes": [
    {"say": "Season four leaves the household. Jonestown. Told by Tom [Bogue](/bˈOɡ/), taken in as a small child, and his father Jim, in his first recorded interview in forty years.",
     "card": {"t": "title", "big": "Escaping\nJonestown", "small": "the Bogue family · 1965–1978"}},
    {"say": "Same cycle, at the scale of a group. Jim came grieving a drowned son and found a potluck, and a community based on equality and love. Then love depended on performance. He slept in the dog house for weeks.",
     "card": {"t": "cycle", "label": "the Bogues", "marks": "yyyyyy"}},
    {"say": "Families were broken up by design. You didn't dare talk to your spouse. And if you didn't denounce a relative in trouble, you were both in trouble.",
     "card": {"t": "quote", "q": "You didn't dare talk to your spouse.", "by": "season 4"}},
    {"say": "Then something new. The record was turned against the victims. Members signed blank sheets for letters to politicians. They became confessions to molesting their own children, held over anyone who tried to leave.",
     "card": {"t": "head", "head": "Blank sheets became\nfalse confessions.", "body": "The record, manufactured against the victims."}},
    {"say": "The state's instruments were in play. Tom says a district attorney was a member. A sheriff's deputy served Jim an eviction the day after he said he was quitting.",
     "card": {"t": "head", "head": "The state, captured.", "body": "A member DA (per Tom) · a deputy's eviction order"}},
    {"say": "Tom's own read on variance:",
     "card": {"t": "quote", "q": "A lot of variations to every story… but they all have a common foundation.", "by": "Tom Bogue"}},
    {"say": "Nine hundred and eighteen people died at Jonestown.",
     "card": {"t": "stat", "num": "918", "label": "died at Jonestown, 18 November 1978"}},
  ]},

  {"id": "06", "kicker": "SEASON 5 · 2020", "accent": "#3fd0c9", "scenes": [
    {"say": "Season five. Three survivors. Julia, in a youth ministry. Kelly, married to the youth pastor. Rachel, raised by a pastor father and an enforcer mother.",
     "card": {"t": "list", "head": "Three survivors", "items": ["Julia · a youth ministry", "Kelly · married to the youth pastor", "Rachel · a pastor's household"]}},
    {"say": "A caveat I logged. Julia and Kelly describe the same church and the same senior pastor. Two witnesses to one institution. Not independent cases.",
     "card": {"t": "head", "head": "Two witnesses.\nOne institution.", "body": "Logged as corroboration, not independence."}},
    {"say": "Kelly's counsellor was chosen by her husband as neutral, was paid by the church, and passed on what she said in session. When she refused to pay five thousand dollars, the counsellor said:",
     "card": {"t": "quote", "q": "I can't control what he will do to you.", "by": "Kelly's counsellor, as she recounts it"}},
    {"say": "Rachel's father confessed his violence in front of the congregation, and was praised for his bravery. Rachel: in that moment, I knew no one was ever going to help us.",
     "card": {"t": "quote", "q": "In that moment, I knew no one was ever going to help us.", "by": "Rachel"}},
    {"say": "The ideology was the vehicle, not the cause. Rachel again:",
     "card": {"t": "quote", "q": "It wasn't the belief system. It was the abusive people who always use whatever they can to control people.", "by": "Rachel"}},
    {"say": "And what finally moved the authorities wasn't one report. Single reports went nowhere. Three converging reports did. Even then, only the abuse with evidence from the time could be charged.",
     "card": {"t": "stat", "num": "3", "label": "converging reports moved the authorities. One never did."}},
  ]},

  {"id": "07", "kicker": "SEASON 6 · 2020", "accent": "#ffb547", "scenes": [
    {"say": "Season six turned into a test I hadn't planned. Most of its stories aren't relationships at all. A stranger met through a dating app. A predatory landlord. A hate crime, followed by years of targeted calls.",
     "card": {"t": "list", "head": "No relationship", "items": ["A stranger from a dating app", "A predatory landlord", "A hate crime, then years of calls"]}},
    {"say": "So the cycle should be missing there. And it was. Only one case, a long friendship built on a catfish, showed it.",
     "card": {"t": "cycle", "label": "a stranger's lure", "marks": "nnnnnn"}},
    {"say": "That matters. A codebook that finds love bombing in a stranger's threats is measuring the coder, not the stories.",
     "card": {"t": "head", "head": "Specificity.", "body": "The cycle didn't appear where it shouldn't."}},
    {"say": "What did cross the boundary were devices. Invented personas. Staged vulnerability. Victim blaming. Erasure.",
     "card": {"t": "list", "head": "Devices that crossed over", "items": ["Invented personas", "Staged vulnerability", "Victim blaming", "Erasure"]}},
    {"say": "And the clearest before and after in the corpus. J.E. Reich's family was targeted after the Tree of Life massacre. In 2019, calls without recordings went nowhere. Then the family recorded them.",
     "card": {"t": "stat", "num": "238", "label": "recorded calls in discovery — “a fraction” of the total"}},
    {"say": "The result was a guilty plea, including a hate crime count. The record that made the case was built by the people being targeted, while it was still happening.",
     "card": {"t": "head", "head": "The victims built\nthe record.", "body": "Under threat, while it was happening."}},
  ]},

  {"id": "08", "kicker": "THE CORRECTION · BEFORE S7", "accent": "#3fd0c9", "scenes": [
    {"say": "Six seasons in, my method got corrected. The correction was right.",
     "card": {"t": "title", "big": "The\ncorrection.", "small": "codebook amendment 1"}},
    {"say": "I had been scoring discard as absent whenever the target left first. Sarah walked out in season one, and I counted it as a miss for the pattern.",
     "card": {"t": "cycle", "label": "my original coding", "marks": "yyyyny"}},
    {"say": "But her leaving was her move, not his. Low variance was never about the stories or the outcomes. It's about what the perpetrator does.",
     "card": {"t": "head", "head": "Her exit is not\nhis behaviour.", "body": "Discard is now “not observable” when she leaves first."}},
    {"say": "And outcome variance is expected. The clinical literature says the moment someone tries to leave is often the most dangerous.",
     "card": {"t": "head", "head": "Leaving is the\ndangerous time.", "body": "Outcome variance is expected, not a counter-case."}},
    {"say": "So the codebook split in three. Perpetrator behaviour, the only fields that test the claim. Target responses. And outcomes.",
     "card": {"t": "list", "head": "Three kinds of field", "items": ["Perpetrator behaviour · the test", "Target responses · recorded", "Outcomes · recorded"]}},
    {"say": "And one new field. What the perpetrator does when the target leaves, or the pattern is exposed. Response to separation.",
     "card": {"t": "head", "head": "New field:\nresponse to separation.", "body": "Hoover · reversal · smear · legal abuse · stalking · threats"}},
    {"say": "One more. Isolation and smears outlast contact. Someone who leaves and faces nothing new has still lost the people who were told a false story. That loss is part of the pattern, not a neutral ending.",
     "card": {"t": "head", "head": "The smear outlasts\nthe contact.", "body": "Lost relationships are part of the pattern."}},
  ]},

  {"id": "09", "kicker": "SEASON 7 · 2021", "accent": "#ff4d5e", "scenes": [
    {"say": "Season seven. Amy, and her older brother, called Rory on the show. Sibling abuse, and child-to-parent abuse, in a single-mother home.",
     "card": {"t": "title", "big": "Amy\n& “Rory”", "small": "Calabasas · 1990s–2023"}},
    {"say": "Blackmail was his leash. It kept Amy home about sixty school days in one year. He made her take the blame for a fire he lit.",
     "card": {"t": "stat", "num": "≈60", "label": "school days in one year, kept home by blackmail"}},
    {"say": "Their mother put him out six to ten times. Each time: the sob story, then the welcome back in.",
     "card": {"t": "head", "head": "Out. Sob story.\nBack in.", "body": "Six to ten times."}},
    {"say": "In 2007, she told him to clean up the kitchen. He killed her. He later pleaded to second-degree murder.",
     "card": {"t": "head", "head": "She imposed a limit.", "body": "Plea: second-degree murder, 15-to-life (public record)"}},
    {"say": "The host read the research on air. Violent incidents often follow a parent who decides to impose consequences, not the parent who gives in.",
     "card": {"t": "quote", "q": "…a parent who decides to impose consequences, not the parent who gives in.", "by": "research read on air"}},
    {"say": "Then sixteen years of retaliation from prison. Letters about a hitman. At a parole hearing he recited her address. A prison inquiry said it did not meet the criteria for a threat.",
     "card": {"t": "stat", "num": "16 years", "label": "of retaliation, run through the justice system"}},
    {"say": "Amy, on what abusers reach for:",
     "card": {"t": "quote", "q": "If religion and children can be weaponized, mental health can be weaponized as well.", "by": "Amy"}},
  ]},

  {"id": "10", "kicker": "SEASON 8 · 2021", "accent": "#ffb547", "scenes": [
    {"say": "Season eight. Auredian, and her partner's sister-in-law, called Crystal. No romance. No violence. An in-law, and two call centre workplaces.",
     "card": {"t": "title", "big": "Auredian\n& “Crystal”", "small": "an in-law and two workplaces · 2016–2020"}},
    {"say": "The love bombing was sistership.",
     "card": {"t": "quote", "q": "She was really preying on that sisterly desire.", "by": "Auredian"}},
    {"say": "Then the corpus's paradigm case of a tailored smear. To coworkers, Crystal's husband was dead, in shifting versions. To Zachary, her in-laws were evil. To Amber's team, Amber hated them. To the nail technician, her mother was dying of cancer.",
     "card": {"t": "list", "head": "One person, many stories", "items": ["Coworkers: “my husband died”", "Zachary: “my in-laws are evil”", "Amber's team: “she hates you”", "Nail tech: “my mom has cancer”"]}},
    {"say": "And a wall between the audiences. To Auredian: watch out for Zachary, he's a pathological liar. Auredian thinks that was the point. To keep them from comparing.",
     "card": {"t": "quote", "q": "Watch out for Zachary. He's a pathological liar.", "by": "“Crystal,” to Auredian"}},
    {"say": "It collapsed the moment people compared notes. Amber called it a house of cards.",
     "card": {"t": "head", "head": "It collapsed when\nthey compared notes.", "body": "“…your whole flimsy house of cards is going to come falling down.”"}},
    {"say": "Two independent workplace witnesses. No single person could see the pattern. It was proven only by putting the accounts side by side.",
     "card": {"t": "cycle", "label": "Auredian", "marks": "yyyyyy"}},
  ]},

  {"id": "11", "kicker": "SEASON 9 · 2021", "accent": "#a78bfa", "scenes": [
    {"say": "Season nine. One man, called Arty. He presented as a British, Oxford-trained doctor. Under cross-examination, he admitted he was not a licensed doctor.",
     "card": {"t": "title", "big": "Danielle,\nKenji & “Arty”", "small": "Los Angeles area · 2011–2023"}},
    {"say": "At least ten women, over about fifteen years. The same devices recur. His name tattooed on three of them. Cars in the women's names. Partners' jobs attacked.",
     "card": {"t": "stat", "num": "10+", "label": "women over ≈15 years — the same devices"}},
    {"say": "Each target got a tailored persona, and a wall. Darcy was told: I'm never allowed to talk to his ex.",
     "card": {"t": "quote", "q": "I'm never allowed to talk to his ex.", "by": "Darcy"}},
    {"say": "Danielle stayed because she foresaw what leaving would bring. When she left, he came to her parents' door at eleven at night. Then the text: let me see my daughter or nobody in this family is going to be safe.",
     "card": {"t": "quote", "q": "Let me see my daughter or nobody in this family is going to be safe.", "by": "text read on air"}},
    {"say": "A family court denied her restraining order. The judge's reasoning:",
     "card": {"t": "quote", "q": "If you really felt threatened you would have left the first time.", "by": "family court, 2020"}},
    {"say": "That's the separation-danger finding from the literature, inverted on the bench.",
     "card": {"t": "head", "head": "The research,\ninverted on the bench.", "body": "She stayed because she foresaw the danger."}},
    {"say": "What worked was targets comparing notes. In 2023, Danielle got full custody, with zero visitation. No criminal conviction is reported.",
     "card": {"t": "head", "head": "What worked:\ncomparing notes.", "body": "2023: full custody, zero visitation · no conviction reported"}},
  ]},

  {"id": "12", "kicker": "SEASON 10 · 2021", "accent": "#3fd0c9", "scenes": [
    {"say": "Season ten is an anthology. Eleven stories. Six are intimate partners that can be coded on the cycle. Five work as a scope test.",
     "card": {"t": "stat", "num": "11", "label": "stories · 6 coded on the cycle · 5 scope tests"}},
    {"say": "Response to separation showed up in all six cycle cases. From a guilt trip, to stalking, to a car chase through highway traffic, to a fight with police.",
     "card": {"t": "stat", "num": "6 / 6", "label": "cycle cases with a response to separation"}},
    {"say": "But this season also broke my headline. I had said no case shows a stage absent while the perpetrator had the chance.",
     "card": {"t": "head", "head": "My headline broke.", "body": "“No stage absent where he had the chance.”"}},
    {"say": "In Emily's case, after his first theft, her husband courted her friends and family at dinners, to reassure them. The network wasn't cut off. It was used.",
     "card": {"t": "cycle", "label": "Emily", "marks": "ypnpod"}},
    {"say": "Isolation, inverted. I withdrew the claim instead of rescuing it.",
     "card": {"t": "head", "head": "Claim withdrawn.", "body": "Not rescued."}},
    {"say": "And a boundary case. Olivia's motherly coworker friend gave gifts, told a false caring story, faked a job. But no devaluation, no isolation, no smear. When she was exposed, she fled.",
     "card": {"t": "cycle", "label": "Olivia", "marks": "pnnnnn"}},
    {"say": "The lesson. Deception and gifts don't make the pattern. The control sequence does, and what happens when you leave.",
     "card": {"t": "head", "head": "Gifts and lies\naren't the pattern.", "body": "Control, and the response to leaving, are."}},
  ]},

  {"id": "13", "kicker": "ACROSS TEN SEASONS", "accent": "#ff4d5e", "scenes": [
    {"say": "Ten seasons. Nineteen target cases coded on the cycle. Here's the tally, on perpetrator behaviour only.",
     "card": {"t": "stat", "num": "19", "label": "target cases coded on the cycle"}},
    {"say": "Response to separation or exposure: nineteen of nineteen. Devaluation: eighteen. Poisoning the well: seventeen. Isolation: fifteen, including the one case where it was inverted.",
     "card": {"t": "bars", "head": "Present, of 19 cases", "rows": [["Response to separation", 19], ["Devaluation", 18], ["Poisoning the well", 17], ["Isolation", 15]], "ref": 19}},
    {"say": "Love bombing held in function in every case, in at least fourteen different forms. Romance. Group belonging. Need. Sistership. A rescuer. A lodger.",
     "card": {"t": "stat", "num": "14+", "label": "forms of love bombing — one function"}},
    {"say": "But love bombing alone tells you nothing. It shows up where there's no control at all. What discriminates is devaluation, isolation, the smear, and above all what happens when you leave.",
     "card": {"t": "head", "head": "Love bombing alone\ndoesn't discriminate.", "body": "The control sequence and the response to leaving do."}},
    {"say": "I first said the podcast's selection inflated the pattern. That was backwards. The people it can't hold are the ones killed at exit, which would strengthen it, and the ones still inside, where nothing has been triggered yet.",
     "card": {"t": "head", "head": "The selection bias\nruns the other way.", "body": "Those killed at exit would strengthen the pattern."}},
    {"say": "The real counter-cases are people who left and faced nothing new. Even they lost the world the smear captured.",
     "card": {"t": "head", "head": "The real counter-case:", "body": "left, and nothing new happened. Watch for it."}},
    {"say": "So the corpus can't say how often perpetrators retaliate. That needs population studies. It can say what kind of thing they do when they do.",
     "card": {"t": "head", "head": "Not how often.\nWhat kind.", "body": "Rates need population studies."}},
  ]},

  {"id": "14", "kicker": "THE DEVICES", "accent": "#ffb547", "scenes": [
    {"say": "Across perpetrators who never knew each other, the same devices kept coming back.",
     "card": {"t": "title", "big": "Same\ndevices.", "small": "perpetrators who never knew each other"}},
    {"say": "Fabricated cancer, illness or death, used as currency. Seasons one, two, six, eight, nine and ten.",
     "card": {"t": "head", "head": "Fabricated illness\nor death.", "body": "S1 · S2 · S6 · S8 · S9 · S10"}},
    {"say": "A suicide threat or performance used as a leash. Seasons one, two, four, five, six and ten.",
     "card": {"t": "head", "head": "Suicide as a leash.", "body": "S1 · S2 · S4 · S5 · S6 · S10"}},
    {"say": "Invented third parties. Sockpuppets, relays, a whole fictional cast. Seasons one, three, five, six and ten.",
     "card": {"t": "head", "head": "Invented people.", "body": "S1 · S3 · S5 · S6 · S10"}},
    {"say": "Attacks on the target's job: eight, nine and ten. Pets harmed or held hostage: one, two, five and ten.",
     "card": {"t": "list", "head": "Also recurring", "items": ["Attacks on her job · S8 S9 S10", "Pets harmed or held hostage · S1 S2 S5 S10"]}},
    {"say": "The perpetrator recast as the victim at the moment of exposure: nine separate cases.",
     "card": {"t": "stat", "num": "9", "label": "cases of reversal on exposure — “I'm the one wronged”"}},
    {"say": "And these structures collapse the same way: targets comparing notes. Two ex-wives in season ten turned it into a method. They check whether he's telling each of them a different story.",
     "card": {"t": "head", "head": "They collapse the same way.", "body": "Targets comparing notes · S8 · S9 · S10"}},
  ]},

  {"id": "15", "kicker": "THE COUNTED TEST", "accent": "#3fd0c9", "scenes": [
    {"say": "Alongside the close-read there was a counted test. Three hundred and eighty-two unique episodes across twenty-six seasons, against sixty-one episodes of The Moth as a control.",
     "card": {"t": "stat", "num": "382", "label": "episodes, 26 seasons · control: 61 episodes of The Moth"}},
    {"say": "Words for the harm, like gaslighting and love bombing, ran at eleven point eight times the control rate. Reversal, six point nine. Isolation, three point four. Threats and stalking, two point three.",
     "card": {"t": "bars", "head": "Rate vs. control (×)", "rows": [["Frame vocabulary", 11.8], ["Reversal", 6.9], ["Isolation", 3.4], ["Threats / stalking", 2.3]], "ref": 12}},
    {"say": "My pre-registered bar for nearly every season was seventy-five percent. Isolation reached twenty-seven. Perception control, forty-six. That criterion failed, and I let the failure stand.",
     "card": {"t": "bars", "head": "Seasons elevated (pre-registered)", "rows": [["Bar to pass", 75, "ref"], ["Perception control", 46], ["Isolation", 27]], "ref": 100, "pct": True}},
    {"say": "What passed: the seasons resemble each other more than ordinary storytelling does. And that holds in the half of the corpus with the least clinical vocabulary. So the convergence isn't just the show's words.",
     "card": {"t": "head", "head": "Passed: the seasons\nconverge.", "body": "Even where the vocabulary is thinnest."}},
    {"say": "No detectable difference by setting. Weak evidence, though. Twenty-five seasons, and thirteen of them intimate partners.",
     "card": {"t": "head", "head": "No setting effect found.", "body": "Weak evidence: n = 25, unbalanced."}},
    {"say": "Verdict on low variance across settings: supported, with qualifications. Not nearly every case.",
     "card": {"t": "title", "big": "Supported.\nQualified.", "small": "not “nearly every case”"}},
  ]},

  {"id": "16", "kicker": "AUDITING MYSELF", "accent": "#a78bfa", "scenes": [
    {"say": "Then I was asked to audit my own study for sycophancy to power. Where did I put the heavier burden on the claim that implicates institutions?",
     "card": {"t": "title", "big": "Where did\nthe burden fall?", "small": "a sycophancy-to-power audit"}},
    {"say": "Everywhere. The claim about institutions got a stricter verdict rule than the claim about individual abusers.",
     "card": {"t": "head", "head": "Two verdict rules.", "body": "The stricter one went to the institutional claim."}},
    {"say": "I checked the institutional measure for noise and used it against the claim. I never checked isolation, which turned out just as noisy.",
     "card": {"t": "head", "head": "Scrutiny, one-sided.", "body": "Institutional ≈ ½ precise · isolation ≈ 55% — equally noisy"}},
    {"say": "My filter cut the update episodes, where police and courts actually respond. And I wrote the troubled-teen industry instead of naming anyone.",
     "card": {"t": "list", "head": "Also", "items": ["Filtered out the aftermath episodes", "Generic labels instead of names"]}},
    {"say": "The show and its sources do name them. At Trails Carolina, as reported, a twelve-year-old died within twenty-four hours of arriving. The medical examiner listed homicide. No charges were filed.",
     "card": {"t": "head", "head": "Trails Carolina, 2024.", "body": "As reported: ruled homicide · no charges filed"}},
    {"say": "Every error ran the same direction. A note written the day before warned about exactly this, and it happened anyway. So now it's a rule: one verdict rule and one audit rule, applied to every criterion before any verdict is written.",
     "card": {"t": "head", "head": "Every error ran\none direction.", "body": "Now a rule, not a note."}},
  ]},

  {"id": "17", "kicker": "BOUNDARY", "accent": "#ff4d5e", "scenes": [
    {"say": "So what does this establish, and what doesn't it?",
     "card": {"t": "title", "big": "What it shows.\nWhat it doesn't.", "small": "the boundary"}},
    {"say": "Across a youth ministry, a vet clinic, a cult, a call centre, a marriage and a family home, the perpetrator's moves converge in function. The vehicle changes. The use doesn't.",
     "card": {"t": "head", "head": "The vehicle changes.\nThe use doesn't.", "body": "Said independently by three survivors."}},
    {"say": "It does not give prevalence. One curator chose these stories, a survivor herself. One selection process can't tell you how common anything is.",
     "card": {"t": "head", "head": "No prevalence rates.", "body": "One curator · one selection process"}},
    {"say": "Same moves doesn't mean coordination. It's a shared move set, not a conspiracy. And none of this is a finding about any person. These are survivors' accounts.",
     "card": {"t": "head", "head": "Structural identity\nis not coordination.", "body": "Accounts, not verdicts."}},
    {"say": "Through all of it runs the documentation burden. The record that finally moved anything was made by the people being harmed, usually at their worst. Syringes kept. Calls recorded. A seventy-five page timeline.",
     "card": {"t": "list", "head": "Who made the record", "items": ["The syringes T kept", "The calls J.E.'s family recorded", "Kenji's 75-page timeline"]}},
    {"say": "A single story is an instance. The pattern is the proof.",
     "card": {"t": "title", "big": "An instance.\nA pattern.", "small": "the pattern is the proof"}},
    {"say": "If something is wrong for you, in the US, the National Domestic Violence Hotline is one eight hundred, seven nine nine, seven two three three. Or text START to eight eight seven eight eight.",
     "card": {"t": "head", "head": "1-800-799-7233", "body": "National Domestic Violence Hotline (US) · text START to 88788"}},
  ]},
]
